import{_ as t,o as r,c as s,ak as o}from"./chunks/framework.sV-XtlWr.js";const n="/screenshots/permission-grid.png",u=JSON.parse('{"title":"Access, roles and groups","description":"Give each person the rights their job needs, project by project: the five project roles and what each can do, groups, who manages access, and the permission grid.","frontmatter":{"title":"Access, roles and groups","description":"Give each person the rights their job needs, project by project: the five project roles and what each can do, groups, who manages access, and the permission grid.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/operate/project-access.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/operate/project-access.html"}],["meta",{"property":"og:title","content":"Access, roles and groups | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Give each person the rights their job needs, project by project: the five project roles and what each can do, groups, who manages access, and the permission grid."}]]},"headers":[],"relativePath":"operate/project-access.md","filePath":"operate/project-access.md","lastUpdated":1791298708000}'),a={name:"operate/project-access.md"};function d(i,e,l,c,h,g){return r(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="access-roles-and-groups" tabindex="-1">Access, roles and groups <a class="header-anchor" href="#access-roles-and-groups" aria-label="Permalink to &quot;Access, roles and groups&quot;">​</a></h1><p>With <a href="./authentication.html">authentication</a> on, what a signed-in user can do inside a project comes from the <strong>project roles</strong> they hold there. An Administrator can do everything on every project. A Member can do only what their project roles allow, granted to them directly or to one of their groups; a Member with no role sees an empty dashboard.</p><h2 id="project-roles" tabindex="-1">Project roles <a class="header-anchor" href="#project-roles" aria-label="Permalink to &quot;Project roles&quot;">​</a></h2><p>A project role is a fixed set of rights inside a project, granted to a user or a group, on one project or on all projects. The first four build on each other, each including everything the one before it can do. Uploader stands apart.</p><table tabindex="0"><thead><tr><th>Role</th><th>Typical holder</th><th>What it is for</th></tr></thead><tbody><tr><td><strong>Viewer</strong></td><td>stakeholder</td><td>Reads everything in the project.</td></tr><tr><td><strong>Contributor</strong></td><td>product owner, manager</td><td>Files issues, pins links, edits bug reports, schedules reports, adds markers.</td></tr><tr><td><strong>Maintainer</strong></td><td>QA engineer, developer</td><td>Triages failures, quarantines tests, runs AI diagnosis, uploads runs, creates share links.</td></tr><tr><td><strong>Project admin</strong></td><td>QA lead, tech lead</td><td>Edits the project settings and members, deletes runs.</td></tr><tr><td><strong>Uploader</strong></td><td>CI account</td><td>For CI: reads the project and uploads runs, nothing else.</td></tr></tbody></table><h2 id="what-each-role-can-do" tabindex="-1">What each role can do <a class="header-anchor" href="#what-each-role-can-do" aria-label="Permalink to &quot;What each role can do&quot;">​</a></h2><p>Each row is one permission. The <strong>Permission</strong> column is how the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a> name each endpoint&#39;s requirement (<code>x-required-permission</code>), so a script author can tell which role a call needs. In the app, <strong>Settings → Roles</strong> shows the same table to every signed-in user.</p><table tabindex="0"><thead><tr><th>What you can do</th><th>Permission</th><th style="text-align:center;">Viewer</th><th style="text-align:center;">Contributor</th><th style="text-align:center;">Maintainer</th><th style="text-align:center;">Project admin</th><th style="text-align:center;">Uploader</th></tr></thead><tbody><tr><td>Read runs, executions, clusters, analytics</td><td><code>project:read</code></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td>File a Jira issue</td><td><code>issue:create</code></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Pin, edit and remove links</td><td><code>link:write</code></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Edit a bug report</td><td><code>bug-report:write</code></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Save and schedule reports</td><td><code>report:write</code></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Add and edit timeline markers</td><td><code>marker:write</code></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Create share links, share a dashboard</td><td><code>share:create</code></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Triage clusters and gaps</td><td><code>triage:write</code></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Quarantine and release tests</td><td><code>quarantine:write</code></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Run AI diagnosis (spends tokens)</td><td><code>ai:run</code></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Re-run in CI, bisect, Flake Lab, fix attempts</td><td><code>run:control</code></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Edit selections and test functions</td><td><code>test-assets:write</code></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Upload runs</td><td><code>run:submit</code></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td>Edit project settings and Jira binding</td><td><code>project:manage</code></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Manage the project&#39;s members</td><td><code>project:members</code></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Delete runs, release kept runs</td><td><code>run:delete</code></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr></tbody></table><p>Only an Administrator holds the <strong>instance permissions</strong>: <code>users:manage</code>, <code>groups:manage</code>, <code>settings:manage</code>, <code>connections:manage</code>, <code>storage:manage</code>, <code>tags:manage</code>, <code>project:create</code> and <code>project:delete</code>. An endpoint any signed-in user may call (their profile, API keys, dashboards, channels, subscriptions) declares <code>signed-in</code>.</p><h2 id="all-projects-or-one-project" tabindex="-1">All projects or one project <a class="header-anchor" href="#all-projects-or-one-project" aria-label="Permalink to &quot;All projects or one project&quot;">​</a></h2><p>A role is granted on one project, or on <strong>All projects</strong>, which also covers projects created later. A user&#39;s rights on a project are the <strong>union</strong> of every role they hold there, on that project and on All projects, directly and through each of their groups. Maintainer on All projects plus Project admin on <code>web-app</code> means Project admin on <code>web-app</code> and Maintainer everywhere else.</p><p>Results sent under a new project name create the project only for an account that can upload on All projects.</p><h2 id="groups" tabindex="-1">Groups <a class="header-anchor" href="#groups" aria-label="Permalink to &quot;Groups&quot;">​</a></h2><p>A group is a named set of users, such as <em>QA</em>, <em>Product owners</em> or <em>CI</em>. It receives project roles the way a user does, so a new hire gets their access by joining groups. Administrators create, rename and delete groups and edit their members in <strong>Settings → Groups</strong>.</p><ul><li><strong>Rights add up.</strong> A user in <em>Product owners</em> (Contributor on All projects) and <em>QA</em> (Maintainer on All projects) can do what a Maintainer does everywhere.</li><li><strong>No deny rules.</strong> To take a right away, remove the role that grants it.</li><li><strong>No nested groups.</strong> A group holds users, never other groups.</li><li><strong>A group never makes anyone an Administrator.</strong> That instance role is granted to a user, on their own row in <strong>Settings → Users</strong>.</li></ul><h2 id="who-manages-access" tabindex="-1">Who manages access <a class="header-anchor" href="#who-manages-access" aria-label="Permalink to &quot;Who manages access&quot;">​</a></h2><p><strong>Administrators</strong> manage everything: users, groups, and roles on every project and on All projects. A <strong>Project admin</strong> manages the members of their own projects and may grant any project role there, Project admin included, but cannot change roles on other projects or on All projects.</p><p>Roles are granted from four places, which all edit the same grants:</p><ul><li><strong>Settings → Permissions</strong>, the <a href="#permission-grid">permission grid</a>: every group and user against every project.</li><li><strong>Settings → Users → Project roles</strong>, the action next to a user: their role on All projects and on each project, with the groups that add to them.</li><li>A project&#39;s <strong>Settings → Members</strong>: the users and groups with a role on that project. Project admins see it for their own projects.</li><li><strong>Settings → Groups</strong> for who belongs to each group; its roles are set on the grid or in a project&#39;s Members.</li></ul><p>Scripts read and change the same grants, called role bindings, through the API; see the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a>.</p><h2 id="permission-grid" tabindex="-1">Permission grid <a class="header-anchor" href="#permission-grid" aria-label="Permalink to &quot;Permission grid&quot;">​</a></h2><p><strong>Settings → Permissions</strong> lays every group and user against every project on one grid. Groups come first, above the users; columns are projects, after an <strong>All projects</strong> column. Each cell is a role selector: pick a role to grant it there, or none to remove it.</p><div class="doc-screenshot"><img src="'+n+'" alt="Settings → Permissions: groups above users down the side, projects across the top, and a role selector in each cell"></div><ul><li><strong>Every change saves at once.</strong> A change the server refuses is rolled back and reported.</li><li><strong>Inherited roles show faint.</strong> A role a user holds only through a group or All projects appears faint, and its tooltip names its source.</li><li><strong>All projects</strong> also covers projects created later. Removing a role there leaves the per-project roles as they were.</li><li><strong>Administrators</strong> can do everything everywhere, so their row is locked.</li><li><strong>Hovering or focusing a cell highlights its row and column.</strong> Tab enters the grid as one stop, the arrow keys move between cells, and Space or Enter opens the role selector.</li><li><strong>Filter users</strong> and <strong>Filter projects</strong> narrow the grid on a large instance.</li></ul><h2 id="default-is-no-access" tabindex="-1">Default is no access <a class="header-anchor" href="#default-is-no-access" aria-label="Permalink to &quot;Default is no access&quot;">​</a></h2><p>A new Member, added in <strong>Settings → Users</strong> or created by an <a href="./authentication.html#oauth-google-github">OAuth</a> sign-in, holds no role and sees an empty dashboard until you grant one, as does an account whose last role you remove. A project the user has no role on is left out of the project list, sidebar, home dashboard, recent runs and search, and its runs, test cases and clusters return <strong>403</strong>.</p><h2 id="ci-accounts" tabindex="-1">CI accounts <a class="header-anchor" href="#ci-accounts" aria-label="Permalink to &quot;CI accounts&quot;">​</a></h2><p>Run the reporter in CI as a Member with the <strong>Uploader</strong> role, through an <a href="./api-keys.html">API key</a>: it reads the project and uploads runs, nothing else. Grant it on All projects when CI should create projects from a new project name, else on the projects it reports to.</p><h2 id="upgrading-from-the-three-roles" tabindex="-1">Upgrading from the three roles <a class="header-anchor" href="#upgrading-from-the-three-roles" aria-label="Permalink to &quot;Upgrading from the three roles&quot;">​</a></h2><p>Earlier versions had three instance-wide roles (Administrator, Reporter, User) and assigned projects to each account. The upgrade converts them:</p><ul><li><strong>Administrator</strong> stays Administrator.</li><li><strong>Reporter</strong> becomes a Member with the Maintainer role on the same projects.</li><li><strong>User</strong> becomes a Member with the Viewer role on the same projects.</li></ul><p>Access to all projects becomes a role on All projects. A Maintainer can do exactly what a Reporter could, and a Viewer what a User could, so nobody gains or loses a right. To narrow a CI account that ran as a Reporter, give it Uploader in place of Maintainer.</p><blockquote><p><strong>Try it in the demo:</strong> the <a href="https://piwitests.dev/demo/" target="_blank" rel="noreferrer">live demo</a> ships with seeded identities, from an administrator to a viewer. Switch between them with the <strong>Acting as</strong> picker in the demo banner and watch the projects and actions change. See <a href="/features/ui-overview.html#live-demo">UI overview → Live demo</a>.</p></blockquote><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./authentication.html">Authentication</a>: turning sign-in on, instance roles and user management</li><li><a href="./api-keys.html">API keys</a>: a key acts with its owner&#39;s instance role and project roles</li><li><a href="./production-checklist.html">Production checklist</a>: what to set before anyone else can reach the instance</li></ul>',35)])])}const m=t(a,[["render",d]]);export{u as __pageData,m as default};
